program = '''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not outside[nr][nc]:
                outside[nr][nc] = True
                q.append((nr, nc))

    inside = [[grid[r][c] == 0 and not outside[r][c] for c in range(w)] for r in range(h)]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if inside[r][c] and any(0 <= r+dr < h and 0 <= c+dc < w and grid[r+dr][c+dc] == 1
                                    for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc):
                out[r][c] = 3

    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or seen[r][c]:
                continue
            comp = []
            q = [(r, c)]
            seen[r][c] = True
            for rr, cc in q:
                comp.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1 and not seen[nr][nc]:
                        seen[nr][nc] = True
                        q.append((nr, nc))
            encloses = any(inside[nr][nc]
                           for rr, cc in comp
                           for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))
                           if 0 <= (nr := rr + dr) < h and 0 <= (nc := cc + dc) < w)
            if encloses:
                for rr, cc in comp:
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = rr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and outside[nr][nc]:
                                out[nr][nc] = 2
    return out
'''
